const item = $input.first().json;
const seed = Math.floor(Math.random() * 1000000000);
const voiceText = String(item.voice_text || '').trim();
if (voiceText.length > 40) { throw new Error('voice_text 超过 40 字,5s 视频放不下,请控制在 5-20 字'); }
// 分辨率防护:mini-ai-svr (Strix Halo) 上 RDNA35 加速节点只支持 T<=16500
// 720p(1280x736, 124帧)估算 T~29k -> 原生路径会 OOM 崩溃(2026-08-16 实测)
const latFrames = Math.ceil(item.length / 4) + 1;
const tokensPerFrame = Math.round(item.width / 32) * Math.round(item.height / 32);
const estT = latFrames * tokensPerFrame + 2000;
if (estT > 16000) {
  throw new Error('分辨率超限(估算T~' + estT + ' > 16500):当前机器甜点区为 480p(864x480, <=5s)。720p 不可行(RDNA35 节点上限 T<=16500,原生路径实测崩溃)。请降低 width/height 或 length。');
}
const workflow = {
  '1': {class_type:'UnetLoaderGGUF', inputs:{unet_name:'MiniMax-H3-FL2VA-Pruned-Q8_0.gguf', weight_dtype:'default'}},
  '2': {class_type:'CLIPLoader', inputs:{clip_name:'qwen3vl_32b_minimax_h3_nvfp4_awq.safetensors', type:'minimax'}},
  '3': {class_type:'VAELoader', inputs:{vae_name:'minimax_h3_video_vae_fp16.safetensors'}},
  '4': {class_type:'MiniMaxH3ImageToVideo', inputs:{clip:['2',0], vae:['3',0], prompt:item.prompt, width:item.width, height:item.height, length:item.length}},
  '5': {class_type:'CLIPTextEncode', inputs:{clip:['2',0], text:''}},
  '6': {class_type:'MiniMaxH3SigmaShift', inputs:{model:['12',0], shift_video:12.0, shift_audio:3.0}},
  '7': {class_type:'KSampler', inputs:{model:['6',0], positive:['4',0], negative:['5',0], latent_image:['4',1], seed, steps:item.steps, cfg:1.0, sampler_name:'er_sde', scheduler:'simple', denoise:1.0}},
  '8': {class_type:'VAEDecode', inputs:{samples:['7',0], vae:['3',0]}},
  '9': {class_type:'CreateVideo', inputs:{images:['8',0], fps:24.0, audio:['15',0]}},
  '10': {class_type:'SaveVideo', inputs:{video:['9',0], filename_prefix:'h3_video', format:'mp4', codec:'auto'}},
  '11': {class_type:'RDNA35PatchMiniMaxH3GFX1151Attention', inputs:{model:['1',0], enabled:true, verbose_fallbacks:true}},
  '12': {class_type:'LoraLoaderModelOnly', inputs:{model:['11',0], lora_name:'minimax_h3_lightx2v_turbo_8step.safetensors', strength_model:1.0}},
  '13': {class_type:'VAELoader', inputs:{vae_name:'minimax_h3_audio_vae_fp32.safetensors'}},
  '14': {class_type:'VAEDecodeAudio', inputs:{samples:['7',0], vae:['13',0]}},
  '15': {class_type:'AudioSanitize', inputs:{audio:['14',0]}}
};
if (voiceText) {
  workflow['16'] = {class_type:'EdgeTTS', inputs:{text:voiceText, voice:'zh-CN-XiaoxiaoNeural', rate:0}};
  workflow['17'] = {class_type:'AudioMerge', inputs:{audio1:['15',0], audio2:['16',0], merge_method:'mean'}};
  workflow['9'].inputs.audio = ['17',0];
  workflow['18'] = {class_type:'SubtitleOverlay', inputs:{images:['8',0], text:voiceText, font_size_pct:4.5, position:'bottom', align:'center', outline:true}};
  workflow['9'].inputs.images = ['18',0];
}
return [{ json: { comfy_body: { prompt: workflow, client_id: 'n8n-h3' }, ...item }}];

const fs = require('fs');
const http = require('http');
const promptId = $input.first().json.prompt_id;
const prev = $('Build H3 Workflow').item.json;
function getJson(url) { return new Promise((res, rej) => http.get(url, r => { let d=''; r.on('data',c=>d+=c); r.on('end',()=>{try{res(JSON.parse(d))}catch(e){rej(e)}}); }).on('error', rej)); }
function getBinary(url) { return new Promise((res, rej) => http.get(url, r => { const c=[]; r.on('data',b=>c.push(b)); r.on('end',()=>res(Buffer.concat(c))); }).on('error', rej)); }
async function withRetry(fn, url, tries) { for (let i=0;i<tries;i++){ try { return await fn(url); } catch(e){ if(i===tries-1) throw e; await new Promise(r=>setTimeout(r,2500*(i+1))); } } }
const dl = Date.now() + 1500000; // 25min cap (mutex proxy allows 120min)
let result = null;
while (Date.now() < dl) {
  try {
    const d = await withRetry(getJson, `http://127.0.0.1:8189/history/${promptId}`, 4);
    if (d[promptId]) {
      const e = d[promptId], st = e.status || {};
      if (st.completed) {
        for (const nid in e.outputs || {}) {
          const vids = e.outputs[nid].videos || e.outputs[nid].images || [];
          for (const v of vids) {
            const u = `http://127.0.0.1:8189/view?filename=${v.filename}&subfolder=${v.subfolder||''}&type=output`;
            const buf = await withRetry(getBinary, u, 4);
            const dir = '/home/node/.n8n/h3-videos';
            fs.mkdirSync(dir, {recursive:true});
            const dest = `${dir}/${v.filename}`;
            fs.writeFileSync(dest, buf);
            result = { saved: dest, filename: v.filename };
            break;
          }
          if (result) break;
        }
        break;
      }
      if (st.status_str === 'error') { result = { error: 'workflow error' }; break; }
    }
  } catch(e) { result = { error: 'poll-fail: ' + e.message }; break; }
  await new Promise(r => setTimeout(r, 3000));
}
if (!result) result = { error: 'timeout' };
return [{ json: { ...result, ...prev }}];
